"use client"

import { useEffect, useRef, type ReactNode } from "react"
import * as THREE from "three"
import {
  fractalGlassFragmentShader,
  fractalGlassVertexShader,
} from "@/lib/shaders/fractal-glass"
import { cn } from "@/lib/utils"

export const FRACTAL_GLASS_DEFAULTS = {
  easeFactor: 0.06,
  parallaxStrength: 0.08,
  distortionIntensity: 1.5,
  stripes: 14,
} as const

export const DEFAULT_FRACTAL_GLASS_TEXTURES = [
  "https://cdn.cosmos.so/ef24a640-42da-4133-96a0-4572d2b0ccbe?format=webp",
  "https://cdn.cosmos.so/6d05ef91-722e-4fcc-83c5-765e348ec644?format=webp&w=1200",
] as const

export interface FractalGlassProps {
  textures?: string[]
  textureIndex?: number
  easeFactor?: number
  parallaxStrength?: number
  distortionIntensity?: number
  stripes?: number
  cycleOnClick?: boolean
  onTextureIndexChange?: (index: number) => void
  className?: string
  children?: ReactNode
}

export function FractalGlass({
  textures = [...DEFAULT_FRACTAL_GLASS_TEXTURES],
  textureIndex = 0,
  easeFactor = FRACTAL_GLASS_DEFAULTS.easeFactor,
  parallaxStrength = FRACTAL_GLASS_DEFAULTS.parallaxStrength,
  distortionIntensity = FRACTAL_GLASS_DEFAULTS.distortionIntensity,
  stripes = FRACTAL_GLASS_DEFAULTS.stripes,
  cycleOnClick = true,
  onTextureIndexChange,
  className,
  children,
}: FractalGlassProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)

  const stateRef = useRef({
    textureIndex,
    mouse: { current: { x: 0.5, y: 0.5 }, target: { x: 0.5, y: 0.5 } },
    material: null as THREE.ShaderMaterial | null,
    textures: [] as THREE.Texture[],
    renderer: null as THREE.WebGLRenderer | null,
  })

  useEffect(() => {
    stateRef.current.textureIndex = textureIndex
    const material = stateRef.current.material
    const selectedTex = stateRef.current.textures[textureIndex]
    if (material && selectedTex?.image) {
      material.uniforms.u_texture.value = selectedTex
      material.uniforms.u_imageResolution.value.set(
        selectedTex.image.width,
        selectedTex.image.height,
      )
    }
  }, [textureIndex])

  useEffect(() => {
    const material = stateRef.current.material
    if (!material) return

    material.uniforms.u_parallaxStrength.value = parallaxStrength
    material.uniforms.u_distortionIntensity.value = distortionIntensity
    material.uniforms.u_stripes.value = stripes
  }, [parallaxStrength, distortionIntensity, stripes])

  const handleCycleTexture = () => {
    if (!cycleOnClick || textures.length <= 1) return

    const nextIdx = (stateRef.current.textureIndex + 1) % textures.length
    stateRef.current.textureIndex = nextIdx
    onTextureIndexChange?.(nextIdx)

    const material = stateRef.current.material
    const selectedTex = stateRef.current.textures[nextIdx]
    if (material && selectedTex?.image) {
      material.uniforms.u_texture.value = selectedTex
      material.uniforms.u_imageResolution.value.set(
        selectedTex.image.width,
        selectedTex.image.height,
      )
    }
  }

  useEffect(() => {
    if (!containerRef.current || !canvasRef.current || textures.length === 0) return

    const container = containerRef.current
    const width = container.clientWidth
    const height = container.clientHeight

    const scene = new THREE.Scene()
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)

    const renderer = new THREE.WebGLRenderer({
      canvas: canvasRef.current,
      antialias: true,
      alpha: false,
    })
    renderer.setSize(width, height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    stateRef.current.renderer = renderer

    const uniforms = {
      u_resolution: { value: new THREE.Vector2(width, height) },
      u_imageResolution: { value: new THREE.Vector2(1, 1) },
      u_mouse: { value: new THREE.Vector2(0.5, 0.5) },
      u_texture: { value: new THREE.Texture() },
      u_parallaxStrength: { value: parallaxStrength },
      u_distortionIntensity: { value: distortionIntensity },
      u_stripes: { value: stripes },
    }

    const material = new THREE.ShaderMaterial({
      vertexShader: fractalGlassVertexShader,
      fragmentShader: fractalGlassFragmentShader,
      uniforms,
    })
    stateRef.current.material = material

    const geometry = new THREE.PlaneGeometry(2, 2)
    const mesh = new THREE.Mesh(geometry, material)
    scene.add(mesh)

    const textureLoader = new THREE.TextureLoader()
    stateRef.current.textures = new Array(textures.length)

    textures.forEach((url, index) => {
      textureLoader.load(url, (texture) => {
        texture.minFilter = THREE.LinearFilter
        stateRef.current.textures[index] = texture

        if (index === stateRef.current.textureIndex) {
          material.uniforms.u_texture.value = texture
          material.uniforms.u_imageResolution.value.set(
            texture.image.width,
            texture.image.height,
          )
        }
      })
    })

    const handleMouseMove = (event: MouseEvent) => {
      const rect = container.getBoundingClientRect()
      stateRef.current.mouse.target.x =
        (event.clientX - rect.left) / rect.width
      stateRef.current.mouse.target.y =
        1.0 - (event.clientY - rect.top) / rect.height
    }

    const handleResize = () => {
      const nextWidth = container.clientWidth
      const nextHeight = container.clientHeight
      renderer.setSize(nextWidth, nextHeight)
      material.uniforms.u_resolution.value.set(nextWidth, nextHeight)
    }

    window.addEventListener("mousemove", handleMouseMove)
    window.addEventListener("resize", handleResize)

    let animationId = 0
    const animate = () => {
      animationId = requestAnimationFrame(animate)

      const mouse = stateRef.current.mouse
      mouse.current.x += (mouse.target.x - mouse.current.x) * easeFactor
      mouse.current.y += (mouse.target.y - mouse.current.y) * easeFactor
      material.uniforms.u_mouse.value.set(mouse.current.x, mouse.current.y)

      renderer.render(scene, camera)
    }
    animate()

    return () => {
      cancelAnimationFrame(animationId)
      window.removeEventListener("mousemove", handleMouseMove)
      window.removeEventListener("resize", handleResize)
      geometry.dispose()
      material.dispose()
      stateRef.current.textures.forEach((texture) => texture?.dispose())
      renderer.dispose()
      stateRef.current.material = null
      stateRef.current.renderer = null
      stateRef.current.textures = []
    }
  }, [textures, easeFactor, parallaxStrength, distortionIntensity, stripes])

  return (
    <div
      ref={containerRef}
      onClick={handleCycleTexture}
      className={cn(
        "relative h-full min-h-[min(500px,100%)] w-full overflow-hidden bg-black select-none",
        cycleOnClick && textures.length > 1 ? "cursor-pointer" : "cursor-default",
        className,
      )}
    >
      <canvas
        ref={canvasRef}
        className="pointer-events-none absolute inset-0 block h-full w-full"
        aria-hidden
      />
      {children ? <div className="relative z-10">{children}</div> : null}
    </div>
  )
}

export const fractalGlassVertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position, 1.0);
  }
`

export const fractalGlassFragmentShader = `
  uniform vec2 u_resolution;
  uniform vec2 u_imageResolution;
  uniform vec2 u_mouse;
  uniform sampler2D u_texture;
  uniform float u_parallaxStrength;
  uniform float u_distortionIntensity;
  uniform float u_stripes;

  varying vec2 vUv;

  vec2 getCoverUv(vec2 uv, vec2 screenRes, vec2 imageRes) {
    float screenRatio = screenRes.x / screenRes.y;
    float imageRatio = imageRes.x / imageRes.y;
    vec2 newUv = uv;
    if (screenRatio > imageRatio) {
      float scale = imageRatio / screenRatio;
      newUv.y = (uv.y - 0.5) * scale + 0.5;
    } else {
      float scale = screenRatio / imageRatio;
      newUv.x = (uv.x - 0.5) * scale + 0.5;
    }
    return newUv;
  }

  float displacement(vec2 uv, float stripes) {
    float x = floor(uv.x * stripes);
    float noise = sin(x * 31.12 + uv.y * 0.1) * cos(x * 15.43);
    return fract(noise * 43758.5453) * 2.0 - 1.0;
  }

  float fractalGlass(vec2 uv, float stripes) {
    float distortion = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;

    for (int i = 0; i < 4; i++) {
      distortion += displacement(uv * frequency, stripes) * (amplitude * 0.015);
      frequency *= 2.2;
      amplitude *= 0.5;
    }
    return distortion;
  }

  void main() {
    vec2 uv = getCoverUv(vUv, u_resolution, u_imageResolution);
    float edgeFactor = smoothstep(0.0, 0.3, vUv.x) * smoothstep(1.0, 0.7, vUv.x);
    float glassDistortion = fractalGlass(vUv, u_stripes) * u_distortionIntensity * edgeFactor;

    vec2 mouseOffset = u_mouse - vec2(0.5);
    float parallaxX = mouseOffset.x * u_parallaxStrength * (1.0 + abs(glassDistortion) * 3.0);
    float parallaxY = mouseOffset.y * u_parallaxStrength;

    vec2 finalUv = uv;
    finalUv.x += glassDistortion + parallaxX;
    finalUv.y += parallaxY;
    finalUv = clamp(finalUv, 0.001, 0.999);

    gl_FragColor = texture2D(u_texture, finalUv);
  }
`
